	private void alignL1Bpsk(double[] re,double[] im){double real2=0,imag2=0;int cells=Math.min(1840,re.length);for(int n=0;n<cells;n++){real2+=re[n]*re[n]-im[n]*im[n];imag2+=2*re[n]*im[n];}double angle=-.5*Math.atan2(imag2,real2),c=Math.cos(angle),s=Math.sin(angle);for(int n=0;n<re.length;n++){double x=re[n],y=im[n];re[n]=x*c-y*s;im[n]=x*s+y*c;}}
