			int cell=1840+i/planes,plane=i%planes;double re=cellsR[cell],im=cellsI[cell],metric;int bit;
			if(plane==0){bit=re>0?0:1;metric=Math.abs(re);}
			else if(plane==1){bit=im>0?0:1;metric=Math.abs(im);}
			else if(plane==2){bit=Math.abs(re)>amp4?0:1;metric=Math.abs(Math.abs(re)-amp4);}
			else if(plane==3){bit=Math.abs(im)>amp4?0:1;metric=Math.abs(Math.abs(im)-amp4);}
			else if(plane==4){bit=Math.abs(Math.abs(re)-amp4)>amp2?0:1;metric=Math.abs(Math.abs(Math.abs(re)-amp4)-amp2);}
			else{bit=Math.abs(Math.abs(im)-amp4)>amp2?0:1;metric=Math.abs(Math.abs(Math.abs(im)-amp4)-amp2);}
