		int fefStart=70+(numRf-1)*35;if(s2Field2!=0&&fefStart+34<=protectedBits){r.fefType=read(bits,fefStart,5);r.fefLength=read(bits,fefStart+5,22);r.fefInterval=read(bits,fefStart+27,8);}
